// ══════════════════════ SECTION: CORE (owner: architect — do not restructure) ══════════════════════
window.__errors = [];
const __err = (m) => { window.__errors.push(String(m)); document.title = 'ERROR'; };
window.onerror = (m, s, l) => __err(m + ' @' + (s||'').split('/').pop() + ':' + l);
window.addEventListener('unhandledrejection', e => __err('promise: ' + e.reason));
const _cerr = console.error.bind(console); console.error = (...a) => { __err(a.join(' ')); _cerr(...a); };

import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
// VFX-FIX4 §4 — the Long Night's grade pass. Added here because the composer is built in
// SECTION: MAIN and its extension point (`HOOK: VFX builder — extend buildPost()`) hands
// VFX the composer, not the module scope.
import { ShaderPass } from 'three/addons/postprocessing/ShaderPass.js';

const P = new URLSearchParams(location.search);
// ?test=<suite|all> boots the game under the SHOT discipline (deterministic, no listeners,
// no service worker, staged boot awaited) and then runs the unit suites instead of a shot.
const TESTQ = P.get('test');
const SHOT = P.get('shot') || (TESTQ ? '__test__' : null); // deterministic screenshot preset name
// ══ SPEC_8 §G — THE RUNEBOND MASTER SWITCH ═══════════════════════════════════════════════════
// Runebinding is an EXPERIMENT that ships in the box switched off, and this is the only line in
// the file that decides whether it exists. Everything §G adds — the garrison action, the tether,
// the five riders, the snapshot field — is written `if (RUNEBOND && …)`, so with the flag down the
// feature is not merely inactive, it is unreachable: no branch of it can be entered, no field of
// it is ever written, and the balance matrix therefore reads bit-for-bit what it read before the
// mechanic was written. That is not a hope, it is the reason the flag is a module `const`.
//
// THREE SOURCES, IN THIS ORDER, and each one is answering a different question:
//   `&runebond=1` — the HARNESS. A shot preset or an `rb-` matrix row asks for the flagged game
//     explicitly, which is what lets one file carry both balance suites. `=0` forces it down again
//     so a flagged row can state its own control without clearing a player's setting.
//   localStorage  — the PLAYER's settings toggle, and it is read ONLY in the live branch. Under
//     SHOT the switch is the URL and nothing else, or a developer with the toggle on would silently
//     re-baseline every row of the matrix from their own browser profile.
//   default       — OFF. Promotion to default-ON is an explicit user decision once the rb- suite
//     holds its floors (§G), not something a stage may do by editing a `false` to a `true`.
//
// It is a const because the toggle RELOADS (see UI's btnRb, the language toggle's own pattern):
// bonds are tower state, and a switch that could fall mid-run would have to explain what happens
// to four forged bonds and a purse that already paid for them. A reload with the run snapshotted
// answers that for free, and keeps this a compile-time constant everywhere it is read.
const RB_KEY = 'bannerfall.runebond';
// (the `G.runebond()` read-out is published beside G.autoCall in SIM — `G` itself does not
// exist yet this far up the file.)
const RUNEBOND = P.has('runebond') ? P.get('runebond') !== '0'
  : (!SHOT && (() => { try { return localStorage.getItem(RB_KEY) === '1'; } catch (e) { return false; } })());
// A preset may belong to a map other than the Vale. MAP has to be resolved here in CORE,
// long before SHOT_PRESETS exists, so the binding lives in this one small table. `&map=`
// still wins, so any preset can be shot on any map.
// SPEC5 §B3: `_herald` is pinned to map 2 because it is the only road in the game with two
// spawn gates — the Ember Wastes' fork is a BRANCH off one mouth, and a herald has nothing
// to herald there.
// SPEC6 §A2 — the Barrowmoor's frames. `_risen` moves to map 4 with the map: it was authored
// on the Vale with the engine force-flipped because no undead road existed yet, and its whole
// subject (a cursed wave mid-rise) is now something this campaign actually contains.
const SHOT_MAPS = { overview2: 2, battle2: 2, overview3: 3, battle3: 3, _snow: 2, _ash: 3, _herald: 2,
  overview4: 4, battle4: 4, _dusk: 4, _risen: 4,
  // SPEC6 §E — the hex rig runs on FROSTFELL, because the junction camp it exists to punish
  // is Frostfell's own optimal play. It builds `M2_CAMP`, which is the `junction2` matrix row
  // verbatim, so the frame and the number are the same eight towers.
  // SPEC_8 §B/§E — the Shattered Pass. `overview5` reads the whole weave from above (the frame
  // the lattice thesis lives or dies on); `battle5` is a crossing under fire; `_flanklord` is the
  // finale, i.e. the one preset that renders a boss steering on G.routeCoverage.
  overview5: 5, battle5: 5, _flanklord: 5,
  // SPEC_8 §E — the canyon stage's two: `_cross` is the rope-bridge crossroads read (does a
  // player SEE where fate forks?) and `_gorge` is the merge under a siege ram.
  _cross: 5, _gorge: 5,
  // SPEC_8 §F — the two Shattered Pass natives are judged on the Shattered Pass, because both of
  // their mechanics are functions of ITS geometry: the stalker's phase is keyed to that map's
  // crossings and the charger's gallop to the straights between them. `_troll` is deliberately NOT
  // bound here — see its own note.
  _stalker: 5, _charger: 5,
  _hex: 2 };

// ══ SCHOOLS §0 — A/B PROBES FOR THE CRITIC PANEL ══════════════════════════════════════════
// Three findings in the round-4 VFX set ("the schools share one hue band", "emissive VFX do
// not light neighbouring geometry", "the Long Night is a dimmed day frame") are claims about
// a DIFFERENCE between two frames, and none of them could be measured on the shipped build
// because there was no way to render the second frame. Each flag below removes exactly ONE
// contributor from a preset and changes nothing else, so `frameA − frameB` isolates it:
//   &nohit  — `_elem` stages its eight bodies and skips the eight hits. Subtracting this from
//             `_elem` leaves the four schools' emitted light and NOTHING else, which is the
//             only honest way to ask what hue a school is over a golden-hour meadow.
//   &noblast— the pooled blast PointLights are held at zero. `impact − impact&noblast` IS the
//             answer to "does the fireball light the ground", in dR/dG/dB.
//   &day    — the night grade and the night light rig are forced off for one frame, so
//             `_longnight` can be compared against ITS OWN daylight, not against `battle`.
//   &nosward— the shadow-side terrain grade (INTEGRATE §1) is held at zero, so
//             `ui − ui&nosward` is the whole of that fix and nothing else.
// WORLD-FIX5 added two more, and both earned their keep immediately: round 5 filed the same
// artifact twice (a "detail-band cull" and a "shadow-coverage stripe") and &noshadow settled
// in one A/B that they were one cliff-ring shadow; &rockdbg settled that the boulders the
// panel called unlit already had a correct warm-neutral albedo and a positive N.L, which is
// what pointed at the simultaneous-contrast reading instead of a third lighting bug.
//   &noshadow — the sun stops casting. Separates a shadow-coverage artifact from an albedo one.
//   &rockdbg  — the granite instances render their ALBEDO instead of their shaded result, so a
//             "this rock is the wrong colour" claim can be split into albedo vs lighting.
// VFX-FIX6 §2 adds the seventh, for the same reason the first two exist. Round 6 filed
// "_champion is a milky white-out, a dust/haze veil floods the whole image" — a claim about a
// DIFFERENCE that could not be measured, because there was no way to render the frame without
// the road plume. `_champion - _champion&nodust` is now the whole of the marching veil in
// dSat/dLum, and it is what settled the finding: the veil is worth 0.021 of saturation on the
// road box, and the frame's real black point is 13.9% of pixels under 0.15 luminance (the
// finding asserted "no black point anywhere" and asked for 8%). Kept so the next round can
// re-run the same subtraction instead of re-arguing it.
//   &nodust — the two road-dust emitters and the foot puffs emit nothing.
// All seven are SHOT-only (a player URL cannot reach them) and all seven are inert in the
// default suite, so the shipped frames are byte-identical with or without this block.
const DBG = {
  noHit:   !!SHOT && P.has('nohit'),
  noBlast: !!SHOT && P.has('noblast'),
  day:     !!SHOT && P.has('day'),
  noSward: !!SHOT && P.has('nosward'),
  noShadow: !!SHOT && P.has('noshadow'),
  rockDbg:  !!SHOT && P.has('rockdbg'),
  noDust:   !!SHOT && P.has('nodust'),
  // r11-VFX §2a — the EIGHTH null frame, and it exists for the same reason the first seven do.
  // Round 11 filed "no snowfall, no ashfall" as a claim about a DIFFERENCE (how much of this
  // frame is weather?) that no meter on a single PNG can answer: a speck counter on `battle2`
  // cannot tell a flake from a rock highlight, and after v9's tri-planar grain landed it cannot
  // tell one from ground detail either — measured, a delta-over-local-mean count of the same
  // open-snow crop reports 1028 "specks" at delta 5 and 84 at delta 35, i.e. it reports the
  // terrain. `battle2 - battle2&nowea` IS the weather field, in dL and in coverage, and nothing
  // else. SHOT-only and inert in the default suite, exactly like the other seven.
  noWea:    !!SHOT && P.has('nowea'),
};

// ══ i18n — the string layer (SPEC4 §B) ═══════════════════════════════════════════════════
// EVERY player-facing sentence in the game is a KEY, and the two dictionaries below are the
// only places English or French is written. `L(key, ...args)` resolves it; `{0}`/`{1}` are
// the slots. A missing French key falls back to English rather than printing a key, so a
// half-translated build degrades instead of breaking.
//
// The language is resolved ONCE, here, at module scope — render-side, before a single sim
// tick, never from a wall clock and never out of rng(). Precedence: `&lang=` (the harness
// pins EN, so a critic frame never shifts under a translator), then the saved choice, then
// navigator.language. The settings toggle writes the choice and reloads, which is exactly
// the idiom the quality toggle already uses; nothing re-renders mid-run.
const LANG_KEY = 'bannerfall.lang';
const LANG = (() => {
  const q = (P.get('lang') || '').toLowerCase();
  if (q === 'fr' || q === 'en') return q;                // an explicit request always wins
  if (SHOT) return 'en';                                 // battery default: English
  try { const s = localStorage.getItem(LANG_KEY); if (s === 'fr' || s === 'en') return s; } catch (e) { /* private mode */ }
  return /^fr/i.test(navigator.language || '') ? 'fr' : 'en';
})();
