  // `nk` is `a`, and `grade` collapses to the single lerp that shipped.
  const dk = DUSKC ? Math.min(a, DUSK_FLOOR) / DUSK_FLOOR : 0;
  const nk = DUSKC ? Math.max(0, a - DUSK_FLOOR) / (1 - DUSK_FLOOR) : a;
