              hand: T.BONE, pauld: T.TEAL, skirt: -1, tabard: T.TEAL, tabW: 0.86, chest: -1, face: T.BONE,
              skin: T.BONE, hair: T.BONE, helm: 'skull', shield: 'none', weapon: 'sword',
              knee: false, gait: 1.96, jit: 0.13, aim: 0.90, bladeTint: 0.66, bar: 0.82,
