  for (let i = 0; i < S; i += 3) { g.fillStyle = 'rgba(92,82,62,.07)'; g.fillRect(i, 0, 1, S); g.fillRect(0, i, S, 1); }
  for (let i = 0; i < 4; i++) { g.fillStyle = 'rgba(118,98,70,.17)'; g.fillRect(i * S / 4 + S / 32, 0, S / 14, S); }
