// [.5,0,1,.5] plain field (shields, tent flaps).
const HR_TALL = [0, 0.5, 0.5, 1], HR_PEN = [0.5, 0.5, 1, 1], HR_SQ = [0, 0, 0.5, 0.5], HR_PLAIN = [0.5, 0, 1, 0.5];
