    g.fillStyle = gr; g.fillRect(x, y, w, h);
    for (let i = 0; i < 200; i++) { g.fillStyle = 'rgba(0,0,0,' + (0.03 + wrng() * 0.06) + ')'; g.fillRect(x + wrng() * w, y + wrng() * h, 1 + wrng() * 3, 2 + wrng() * 15); }
