      g2.addColorStop(0, 'rgba(0,0,0,.26)'); g2.addColorStop(0.46, 'rgba(255,248,232,.13)'); g2.addColorStop(1, 'rgba(0,0,0,.24)');
      g.fillStyle = g2; g.fillRect(fx - fw / 2, y, fw, h);
