    vg.addColorStop(0, 'rgba(0,0,0,1)'); vg.addColorStop(0.5, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(0,0,0,1)');
    g2.globalCompositeOperation = 'destination-out'; g2.fillStyle = vg; g2.fillRect(0, 0, S, S);
