    const fl = 0.85 + 0.3 * Math.sin(at * 17 + q.p._id);
    fireQuad(n++, q.x, q.y - 0.30, q.z, 0.78 * fl, 1.15 * fl);
    fireQuad(n++, q.x, q.y - 0.12, q.z, 0.44, 0.70 * fl);
