    G.patches.push({ x: s.x, z: s.z, r: P.rad, dur: P.burn.dur, born: t, owner: 'smite', dps: P.burn.dps });
    VFX.smite(s.x, s.z, P.rad);
    VFX.shakeAt(s.x, G.groundY(s.x, s.z), s.z, 0.85);
