    const TW2 = 17.5;
    const gr = g.createLinearGradient(-TW2, 0, TW2, 0);
    gr.addColorStop(0, '#8a7b58'); gr.addColorStop(0.30, '#d8c9a2'); gr.addColorStop(0.60, '#bfae86'); gr.addColorStop(1, '#7c6e4f');
    poly(g, [-TW2, 3, TW2, 3, 0, th], gr, '#61553d', 1.2);
