      g.fillStyle = PAL.iron[1]; g.beginPath(); g.ellipse(-20, 7.4, 3.2, 1.7, 0, 0, 7); g.fill();
      const fg = g.createRadialGradient(-20, 9, 0.4, -20, 9.6, 5);
