        g.beginPath(); g.moveTo(0, 1.6); g.lineTo(dx, dy); g.stroke();
        g.strokeStyle = '#9aa6b4'; g.lineWidth = 1.2;
        g.beginPath(); g.moveTo(0, 1.6); g.lineTo(dx * 0.86, dy * 0.86); g.stroke();
