    poly(g, [1.0, 12.0, 13.0, 13.2, 13.8, 17.0, 0.8, 16.2], HDL);                   // lit shoulder
    g.fillStyle = 'rgba(196,176,142,.22)'; g.fillRect(-10.0, 14.2, 22.0, 1.4);       // dust on the spine
