  coopBand();                                           // §C2 — the ally purses
  $('chipMuster').classList.toggle('full', mFull);
  $('chipMuster').title = (mFull ? L('mus.fullT') : '') +
    (G.musterCost() === undefined ? L('mus.capT') : L('mus.raiseT', G.musterCost()));
