const STAT0 = () => ({ burn: 0, storm: 0, steel: 0, trap: 0, power: 0, wyv: 0,
                       champ: 0, risen: 0, hex: 0, slow: 0, kind: {} });
let PROG_S = STAT0(), PROG_H = {};
