let laurelsAtStart = 0;
function laurelMark() { laurelsAtStart = laurelsEarned(); }

// ══ DEEDS (SPEC6 §C) ═════════════════════════════════════════════════════════
// Twenty-eight deeds in four registers, each worth exactly one laurel — the loop that pays
