$('btnFps').onclick = () => { $('fpsV').textContent = L(G.setFpsCap(G.fpsCap() === 60 ? 30 : 60) === 30 ? 'fps.30' : 'fps.60'); };
// v7-RESILIENCE §1 — "Restart Campaign" throws the saved run away as well. It used to be a bare
