document.querySelectorAll('.seedTag .sD').forEach(b => { b.onclick = rollSeed; });
$('qualV').textContent = L(tier === 'mobile' ? 'qual.low' : tier === 'ultra' ? 'qual.ultra' : 'qual.high');
