$('rbV').textContent = L(RUNEBOND ? 'val.on' : 'val.off');   // SPEC_8 §G
$('fpsV').textContent = L(G.fpsCap() === 30 ? 'fps.30' : 'fps.60');   // v7-RESILIENCE §3
$('langV').textContent = LANG === 'fr' ? 'Français' : 'English';
