  battle3:  { t: 900, builds: 'm3b', cam: { pos: [-16, 42, 40], look: [26, 1, -26] } },
  // ══ SPEC6 §A2 — THE BARROWMOOR ══════════════════════════════════════════════
  overview4: { t: 2, builds: [], cam: { tgt: [-6, 4, -2], dist: 158 } },
